macro_rules! inflate_flags {
    () => {
        # [doc = " Flags to [`decompress()`] to control how inflation works."] # [doc = ""] # [doc = " These define bits for a bitmask argument."] pub mod inflate_flags { # [doc = " Should we try to parse a zlib header?"] # [doc = ""] # [doc = " If unset, the function will expect an RFC1951 deflate stream.  If set, it will expect a"] # [doc = " RFC1950 zlib wrapper around the deflate stream."] pub const TINFL_FLAG_PARSE_ZLIB_HEADER : u32 = 1 ; # [doc = " There will be more input that hasn't been given to the decompressor yet."] # [doc = ""] # [doc = " This is useful when you want to decompress what you have so far,"] # [doc = " even if you know there is probably more input that hasn't gotten here yet (_e.g._, over a"] # [doc = " network connection).  When [`decompress()`][super::decompress] reaches the end of the input"] # [doc = " without finding the end of the compressed stream, it will return"] # [doc = " [`TINFLStatus::NeedsMoreInput`][super::TINFLStatus::NeedsMoreInput] if this is set,"] # [doc = " indicating that you should get more data before calling again.  If not set, it will return"] # [doc = " [`TINFLStatus::FailedCannotMakeProgress`][super::TINFLStatus::FailedCannotMakeProgress]"] # [doc = " suggesting the stream is corrupt, since you claimed it was all there."] pub const TINFL_FLAG_HAS_MORE_INPUT : u32 = 2 ; # [doc = " The output buffer should not wrap around."] pub const TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF : u32 = 4 ; # [doc = " Calculate the adler32 checksum of the output data even if we're not inflating a zlib stream."] # [doc = ""] # [doc = " If [`TINFL_FLAG_IGNORE_ADLER32`] is specified, it will override this."] # [doc = ""] # [doc = " NOTE: Enabling/disabling this between calls to decompress will result in an incorrect"] # [doc = " checksum."] pub const TINFL_FLAG_COMPUTE_ADLER32 : u32 = 8 ; # [doc = " Ignore adler32 checksum even if we are inflating a zlib stream."] # [doc = ""] # [doc = " Overrides [`TINFL_FLAG_COMPUTE_ADLER32`] if both are enabled."] # [doc = ""] # [doc = " NOTE: This flag does not exist in miniz as it does not support this and is a"] # [doc = " custom addition for miniz_oxide."] # [doc = ""] # [doc = " NOTE: Should not be changed from enabled to disabled after decompression has started,"] # [doc = " this will result in checksum failure (outside the unlikely event where the checksum happens"] # [doc = " to match anyway)."] pub const TINFL_FLAG_IGNORE_ADLER32 : u32 = 64 ; # [doc = " Return [`TINFLStatus::BlockBoundary`][super::TINFLStatus::BlockBoundary]"] # [doc = " on reaching the boundary between deflate blocks. Calling [`decompress()`][super::decompress]"] # [doc = " again will resume decompression of the next block."] # [cfg (feature = "block-boundary")] pub const TINFL_FLAG_STOP_ON_BLOCK_BOUNDARY : u32 = 128 ; }
    };
}

inflate_flags!();